/* Short helper so every product keeps the same shape as data.js. */
const mk = (
  name, brand, category, price, compareAtPrice, stock, rating, count, sold,
  tags, photo, description, highlights, specs, featured = false
) => ({
  name, brand, category, price, compareAtPrice, stock,
  rating: { average: rating, count },
  sold, tags, photo, description, highlights,
  specs: specs.map(([key, value]) => ({ key, value })),
  featured,
});

